import { useEffect, useState } from "react";
import axios from "axios";
import AdminPanel from "./components/AdminPanel";
import AuthPage from "./components/Authpage";
import AdminAnonymousResults from "./components/AdminAnonymousResults";

const API_URL = "http://localhost:5000";

function App() {
  const [candidates, setCandidates] = useState([]);
  const [darkMode, setDarkMode] = useState(false);
  const [showAnonymous, setShowAnonymous] = useState(false);
  const [electionClosed, setElectionClosed] = useState(false);
  const [editId, setEditId] = useState(null);
  const [message, setMessage] = useState("");

  const [auth, setAuth] = useState({
    token: localStorage.getItem("token") || null,
    role: localStorage.getItem("role") || null,
  });

  const [candidateForm, setCandidateForm] = useState({
    firstName: "",
    lastName: "",
    candidacy: "",
    description: "",
    yearLevel: "",
    block: "",
    image: null,
  });

  // ================= FETCH CANDIDATES =================
  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch {
      setMessage("Failed to load candidates.");
    }
  };

  useEffect(() => {
    fetchCandidates();
    const interval = setInterval(fetchCandidates, 2000);
    return () => clearInterval(interval);
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    setAuth({ token: null, role: null });
  };

  // ================= SAVE CANDIDATE =================
  const handleSaveCandidate = async () => {
    try {
      const formData = new FormData();
      formData.append("firstName", candidateForm.firstName);
      formData.append("lastName", candidateForm.lastName);
      formData.append("candidacy", candidateForm.candidacy);
      formData.append("description", candidateForm.description || "");
      formData.append("yearLevel", candidateForm.yearLevel || "");
      formData.append("block", candidateForm.block || "");
      if (candidateForm.image) formData.append("image", candidateForm.image);

      if (editId) {
        await axios.put(`${API_URL}/api/candidates/${editId}`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate updated.");
      } else {
        await axios.post(`${API_URL}/api/candidates`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate added.");
      }

      setCandidateForm({
        firstName: "",
        lastName: "",
        candidacy: "",
        description: "",
        yearLevel: "",
        block: "",
        image: null,
      });

      setEditId(null);
      fetchCandidates();
    } catch {
      setMessage("Failed to save candidate.");
    }
  };

  const handleDeleteCandidate = async (id) => {
    try {
      await axios.delete(`${API_URL}/api/candidates/${id}`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });
      fetchCandidates();
    } catch {
      setMessage("Delete failed.");
    }
  };

  const totalVotes = candidates.reduce(
    (sum, c) => sum + (c.votes || 0),
    0
  );

  if (!auth.token) return <AuthPage setAuth={setAuth} />;

  const theme = {
    background: darkMode ? "#1f1f2e" : "#f4f4f9",
    card: darkMode ? "#2c2c3a" : "#ffffff",
    text: darkMode ? "#f4f4f9" : "#1f1f2e",
    button: darkMode ? "#4f46e5" : "#6366f1",
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        backgroundColor: theme.background,
        color: theme.text,
        padding: 20,
      }}
    >
      {/* HEADER */}
      <div style={{ display: "flex", justifyContent: "space-between" }}>
        <h1>SorSU Online Voting</h1>
        <div>
          <button
            onClick={() => setDarkMode(!darkMode)}
            style={headerButtonStyle(theme)}
          >
            {darkMode ? "Light Mode" : "Dark Mode"}
          </button>

          <button
            onClick={() => setShowAnonymous(!showAnonymous)}
            style={headerButtonStyle(theme)}
          >
            {showAnonymous ? "Hide Anonymous Chart" : "Anonymous Chart"}
          </button>

          {auth.role === "admin" && (
            <button
              onClick={() => setElectionClosed(!electionClosed)}
              style={{
                ...headerButtonStyle(theme),
                backgroundColor: electionClosed
                  ? "#10b981"
                  : "#ef4444",
              }}
            >
              {electionClosed ? "Open Election" : "Close Election"}
            </button>
          )}

          <button
            onClick={handleLogout}
            style={{
              ...headerButtonStyle(theme),
              backgroundColor: "#ef4444",
            }}
          >
            Logout
          </button>
        </div>
      </div>

      {message && <p style={{ marginTop: 10 }}>{message}</p>}

      {/* ADMIN VIEW */}
      {auth.role === "admin" && showAnonymous && (
        <AdminAnonymousResults theme={theme} />
      )}

      {auth.role === "admin" && !showAnonymous && (
        <>
          <h2 style={{ marginTop: 20 }}>Live Vote Monitor</h2>
          <div
            style={{
              backgroundColor: theme.card,
              padding: 15,
              borderRadius: 8,
              marginBottom: 20,
            }}
          >
            <strong>Total Votes:</strong> {totalVotes}
          </div>

          <AdminPanel
            candidateForm={candidateForm}
            setCandidateForm={setCandidateForm}
            onSave={handleSaveCandidate}
            editId={editId}
            setEditId={setEditId}
            onDelete={handleDeleteCandidate}
            candidates={candidates}
            theme={theme}
          />
        </>
      )}

      {/* USER VIEW */}
      {auth.role === "user" && (
        <>
          <h2 style={{ marginTop: 30 }}>Official Ballot</h2>

          {electionClosed ? (
            <div
              style={{
                backgroundColor: "#ef4444",
                padding: 15,
                borderRadius: 8,
                color: "white",
                marginTop: 10,
              }}
            >
              Election is Closed.
            </div>
          ) : candidates.length === 0 ? (
            <p>No candidates available.</p>
          ) : (
            Object.entries(
              candidates.reduce((groups, candidate) => {
                if (!groups[candidate.candidacy]) {
                  groups[candidate.candidacy] = [];
                }
                groups[candidate.candidacy].push(candidate);
                return groups;
              }, {})
            ).map(([position, positionCandidates]) => (
              <div key={position} style={{ marginTop: 40 }}>
                <h3
                  style={{
                    borderBottom: "2px solid gray",
                    paddingBottom: 5,
                  }}
                >
                  {position}
                </h3>

                <div
                  style={{
                    display: "flex",
                    gap: 20,
                    flexWrap: "wrap",
                  }}
                >
                  {positionCandidates.map((candidate) => (
                    <div
                      key={candidate._id}
                      style={{
                        backgroundColor: theme.card,
                        padding: 15,
                        borderRadius: 10,
                        width: 280,
                        boxShadow:
                          "0 4px 10px rgba(0,0,0,0.1)",
                      }}
                    >
                      {candidate.image && (
                        <img
                          src={`${API_URL}/uploads/${candidate.image}`}
                          alt="candidate"
                          style={{
                            width: "100%",
                            height: 200,
                            objectFit: "cover",
                            borderRadius: 8,
                          }}
                        />
                      )}

                      <h4 style={{ marginTop: 10 }}>
                        {candidate.firstName}{" "}
                        {candidate.lastName}
                      </h4>

                      <p style={{ fontSize: 13, opacity: 0.8 }}>
                        {candidate.yearLevel} -{" "}
                        {candidate.block}
                      </p>

                      <p
                        style={{
                          fontSize: 14,
                          marginTop: 8,
                        }}
                      >
                        {candidate.description ||
                          "No platform provided."}
                      </p>

                      <button
                        onClick={async () => {
                          if (
                            window.confirm(
                              `Are you sure you want to vote for ${candidate.firstName} ${candidate.lastName}?`
                            )
                          ) {
                            try {
                              await axios.post(
                                `${API_URL}/api/votes`,
                                {
                                  candidateId:
                                    candidate._id,
                                },
                                {
                                  headers: {
                                    Authorization: `Bearer ${auth.token}`,
                                  },
                                }
                              );
                              setMessage(
                                "Vote cast successfully!"
                              );
                              fetchCandidates();
                            } catch {
                              setMessage(
                                "You already voted or vote failed."
                              );
                            }
                          }
                        }}
                        style={{
                          marginTop: 12,
                          padding: "8px 16px",
                          backgroundColor:
                            theme.button,
                          color: "white",
                          border: "none",
                          borderRadius: 5,
                          cursor: "pointer",
                          width: "100%",
                        }}
                      >
                        Vote
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            ))
          )}
        </>
      )}
    </div>
  );
}

const headerButtonStyle = (theme) => ({
  marginRight: 10,
  padding: "8px 16px",
  backgroundColor: theme.button,
  color: "#fff",
  border: "none",
  borderRadius: 5,
  cursor: "pointer",
});

export default App;
